#!/usr/bin/env bash
# Publish the website and the browser build to GitHub Pages.
#
#   tool/deploy_pages.sh          # build the app, assemble, push to gh-pages
#   SKIP_APP=1 tool/deploy_pages.sh   # pages only (no Flutter build)
#
# Pages serves the `gh-pages` branch root, so the site is `docs/` (generated by
# tool/gen_site.py) plus `app/` (the Flutter web build). A branch, not `docs/` on
# main, because the 40 MB browser build must not sit in the history of a repo that
# people clone; the branch is force-pushed, so it holds exactly one commit.
#
# The project site is always served under /Puzzlestack/, so the app is built with
# that base href and every link in the pages is relative.
set -euo pipefail

ROOT=$(cd "$(dirname "$0")/.." && pwd)
BRANCH=${BRANCH:-gh-pages}
BASE_HREF=${BASE_HREF:-/Puzzlestack/app/}
OUT=$(mktemp -d "${TMPDIR:-/tmp}/puzzlestack-pages.XXXXXX")
trap 'rm -rf "$OUT"' EXIT

echo "== pages"
# The HTML is committed in docs/ (generated, reviewable). Regenerate first so the
# deployed pages are the ones in the repo.
(cd "$ROOT" && [ -n "${REGEN:-}" ] && { dart run tool/site_export.dart; python3 tool/gen_site.py; } || true)
rsync -a --exclude '.git' --exclude 'previews' "$ROOT/docs/" "$OUT/"

if [ -z "${SKIP_APP:-}" ]; then
  echo "== app"
  (cd "$ROOT" && flutter build web --release --base-href "$BASE_HREF")
  # Symbols are debug artefacts the loader never fetches.
  find "$ROOT/build/web" -name '*.symbols' -delete
  rsync -a --delete "$ROOT/build/web/" "$OUT/app/"
fi

cat > "$OUT/.nojekyll" <<<''

echo "== size"
du -sh "$OUT" "$OUT/app" 2>/dev/null || du -sh "$OUT"

echo "== commit"
(
  cd "$OUT"
  git init -q -b "$BRANCH"
  git add -A
  git -c user.name="$(git -C "$ROOT" config user.name)" \
      -c user.email="$(git -C "$ROOT" config user.email)" \
      commit -q -m "site: $(date -u +%Y-%m-%dT%H:%MZ) from $(git -C "$ROOT" rev-parse --short HEAD)"
  git remote add origin "$(git -C "$ROOT" remote get-url origin)"
  git push -q --force origin "$BRANCH"
)

echo "== done: https://cyoren.github.io/Puzzlestack/ (Pages must serve $BRANCH)"
